// Copies the agent part of docs/dash/agent-readme.md (everything before "# Server design") into src/readme.gen.ts,
// the static page GET /v1/readme serves. `--check` fails if the generated file is stale.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const doc = readFileSync(
  join(here, '../../../docs/dash/agent-readme.md'),
  'utf8',
);
const cut = doc.indexOf('\n# Server design');
const agentPart = (cut < 0 ? doc : doc.slice(0, cut)).trimEnd() + '\n';
const src = `// Generated by scripts/gen-readme.mjs from docs/dash/agent-readme.md. Do not edit.\nexport const README_MD = ${JSON.stringify(agentPart)};\n`;
const target = join(here, '../src/readme.gen.ts');
if (process.argv.includes('--check')) {
  let cur = '';
  try {
    cur = readFileSync(target, 'utf8');
  } catch {}
  if (cur !== src) {
    console.error(
      'src/readme.gen.ts is stale: run node scripts/gen-readme.mjs',
    );
    process.exit(1);
  }
} else writeFileSync(target, src);
